def empty_dit(dicts):
    """
    Check if all dictionaries in the list are empty.

    :param dicts: List of dictionaries or a single dictionary.
    :return: True if all dictionaries are empty, False otherwise.
    """
    if isinstance(dicts, dict):
        return len(dicts) == 0
    elif isinstance(dicts, list):
        return all(len(d) == 0 for d in dicts)
    else:
        return False
